{"path": "src/java_module.java", "content": "// Метод ищет активного пользователя по логину.
//
// Возвращаем Optional<User>, а не сам объект, чтобы явно показать,
// что пользователь может отсутствовать (null — плохая практика).
public Optional<User> findActive(String login) {
    // Берём поток из коллекции всех пользователей.
    return users.stream()
        // Первый фильтр: совпадение логина без учёта регистра.
        // equalsIgnoreCase используем, чтобы пользователь мог ввести
        // логин в любом регистре (например, "Admin" и "admin").
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Второй фильтр: пользователь должен быть активным.
        // Активность определяется двумя условиями:
        //   1) пользователь не заблокирован (!u.isBlocked());
        //   2) срок действия учётной записи ещё не истёк
        //      (u.getExpiresAt().isAfter(Instant.now())).
        // Оба условия объединены логическим И, поэтому пропускаем
        // только тех, кто одновременно не заблокирован и не просрочен.
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // findFirst() возвращает первый подходящий элемент в виде Optional.
        // Если подходящего элемента нет, вернётся Optional.empty().
        .findFirst();
}
"}

{"path": "src/csharp_module.cs", "content": "// Метод реализует повторные попытки выполнения асинхронного действия
// с экспоненциальной задержкой между ними (exponential backoff).
//
// Параметры:
//   action  — асинхронная функция, которую нужно выполнить.
//             Возвращает Task<int> — результат в виде целого числа.
//   attempts — максимальное количество попыток выполнения.
//
// Возвращает:
//   int — результат успешного выполнения action.
//
// Исключения:
//   HttpRequestException — игнорируется, если есть ещё попытки;
//                          пробрасывается наружу, если попытки исчерпаны.
//   InvalidOperationException — теоретически недостижимый случай
//                               (на случай, если компилятор/анализатор
//                               требует явного выхода из метода).
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл пробует выполнить action не более attempts раз.
    // Индекс i используется и как счётчик попыток,
    // и как показатель степени для расчёта задержки.
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Выполняем действие и сразу возвращаем его результат.
            // Если action завершилась успешно — метод завершён.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Фильтр when гарантирует, что блок сработает только
            // тогда, когда ещё есть следующая попытка.
            // На последней попытке исключение пробрасывается наружу,
            // что позволяет вызывающему коду узнать о неудаче.
            //
            // Задержка растёт экспоненциально: 200мс, 400мс, 800мс, ...
            // Это классический backoff: при частых сбоях сервера
            // мы не «долбим» его запросами, а даём время на восстановление.
            // Math.Pow(2, i) — степень двойки от номера текущей попытки.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Этот код недостижим: либо action вернула результат,
    // либо на последней попытке было выброшено исключение.
    // Но C# требует, чтобы метод с возвращаемым типом
    // гарантированно завершался значением, поэтому оставляем
    // явный throw с понятным сообщением.
    throw new InvalidOperationException("unreachable");
}
"}

{"path": "src/go_module.go", "content": "// worker — функция-«работник» (worker), которая обрабатывает задачи из канала jobs.
//
// Как это работает:
//   - jobs — входной канал задач (Job). Работник читает из него задачи по одной,
//     пока канал не будет закрыт (range завершится).
//   - results — выходной канал результатов (Result). Сюда работник отправляет
//     успешно обработанные результаты.
//   - wg — указатель на sync.WaitGroup, который позволяет вызывающему коду
//     дождаться завершения всех работников.
//
// Почему именно так:
//   - defer wg.Done() гарантирует, что счётчик WaitGroup будет уменьшён
//     независимо от того, как завершится функция (нормально или с ошибкой).
//     Это защищает от «зависания» main-функции, которая ждёт wg.Wait().
//   - for j := range jobs — идиоматичный способ читать из канала до его закрытия.
//     Альтернатива (for { j := <-jobs }) была бы менее читаемой и не обрабатывала
//     бы закрытие канала автоматически.
//   - При ошибке обработки задачи мы логируем её и продолжаем работу (continue),
//     а не прерываем весь воркер. Это делает систему устойчивой к отдельным
//     ошибкам: одна «плохая» задача не убивает обработку остальных.
//   - Результат отправляется в канал results только при успешной обработке,
//     что позволяет вызывающему коду не обрабатывать ошибки здесь, а получать
//     только валидные результаты.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // Уменьшаем счётчик WaitGroup при выходе из функции.
    // defer гарантирует выполнение даже при панике.
    defer wg.Done()

    // Читаем задачи из канала, пока он не будет закрыт.
    for j := range jobs {
        // Обрабатываем задачу. process возвращает результат и возможную ошибку.
        r, err := process(j)
        if err != nil {
            // Логируем ошибку с идентификатором задачи, чтобы было понятно,
            // какая именно задача не обработалась.
            log.Printf("job %d: %v", j.ID, err)
            // Пропускаем задачу и переходим к следующей.
            continue
        }
        // Отправляем результат в выходной канал.
        // Блокирующая отправка (без select) — намеренное решение:
        // если потребитель результатов не успевает, воркер подождёт.
        // Это естественное «торможение» (backpressure), которое не даёт
        // накопиться огромной очереди в памяти.
        results <- r
    }
}
"}

{"path": "src/typescript_module.ts", "content": "/**
 * Функция debounce (дебаунс) — откладывает вызов переданной функции
 * до тех пор, пока не перестанут приходить вызовы в течение заданного
 * интервала времени.
 *
 * Зачем это нужно:
 * - типичный пример — обработчик ввода в поле: мы хотим выполнить
 *   запрос к серверу не на каждый нажатый символ, а только после
 *   того, как пользователь перестал печатать;
 * - аналогично — ресайз окна, скролл, клики по кнопке и т.д.
 *
 * Как это работает:
 * - при каждом вызове возвращённой функции мы сбрасываем предыдущий
 *   таймер (если он был) и ставим новый;
 * - если вызовы идут чаще, чем `ms`, таймер постоянно сбрасывается
 *   и функция `fn` так и не выполняется;
 * - как только пауза между вызовами становится больше `ms`,
 *   таймер срабатывает и `fn` вызывается один раз с последними
 *   переданными аргументами.
 *
 * @param fn - функция, которую нужно «дебаунсить».
 *             Ограничение `T extends (...a: any[]) => void` гарантирует,
 *             что это функция, принимающая произвольные аргументы
 *             и не возвращающая значение (возврат игнорируется).
 * @param ms - задержка в миллисекундах, по прошествии которой
 *             функция будет вызвана.
 * @returns функция с той же сигнатурой аргументов, что и `fn`,
 *          но с отложенным вызовом.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Объявляется в замыкании, чтобы «жить» между вызовами
  // возвращённой функции и позволяла сбрасывать предыдущий таймер.
  //
  // Тип ReturnType<typeof setTimeout> — это тип, который возвращает
  // setTimeout в текущем окружении:
  //   - в Node.js это объект Timeout,
  //   - в браузере — число (идентификатор таймера).
  // Такой тип делает код кросс-платформенным.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем функцию-обёртку.
  // Parameters<T> — утилитарный тип, который извлекает из типа функции T
  // кортеж её аргументов, поэтому обёртка принимает ровно те же
  // аргументы, что и исходная функция.
  return (...args: Parameters<T>) => {
    // Если таймер уже стоит — отменяем его.
    // Именно это и создаёт эффект «дебаунса»: каждый новый вызов
    // «сбрасывает отсчёт», и функция выполнится только после
    // последней паузы.
    if (t) clearTimeout(t);

    // Ставим новый таймер: по его срабатыванию вызовем `fn`
    // с теми аргументами, которые были переданы в этот раз.
    t = setTimeout(() => fn(...args), ms);
  };
}
"}

{"path": "src/rust_module.rs", "content": "use std::collections::HashMap;

/// Разбирает строку в формате "ключ=значение;ключ=значение;..." в словарь.
///
/// Формат входной строки: пары "ключ=значение", разделённые точкой с запятой.
/// Пример: "name=John;age=30" -> { "name": "John", "age": "30" }
///
/// # Поведение
/// - Ключи приводятся к нижнему регистру и обрезаются по краям (trim).
/// - Значения обрезаются по краям, но регистр сохраняется.
/// - Пары, не содержащие "=", просто отбрасываются (например, пустые
///   сегменты после последнего ";" или некорректные записи).
///
/// # Почему именно так
/// - `split_once('=')` вместо `split('=')` — мы гарантируем, что в паре
///   ровно один разделитель: всё до первого "=" — ключ, всё после — значение.
///   Это защищает от случайных "=" внутри значения.
/// - `filter_map` — удобно отбрасывать сегменты без "=" (например, пустые
///   хвосты), не создавая лишних промежуточных коллекций.
/// - `to_lowercase` для ключей — делает поиск нечувствительным к регистру,
///   что удобно, если ключи приходят из разных источников.
/// - `trim` — убирает случайные пробелы вокруг ключа и значения, которые
///   часто встречаются в пользовательском вводе.
/// - `collect()` в `HashMap` — итоговая структура, позволяющая быстрый
///   доступ по ключу (O(1) в среднем).
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';')
        .filter_map(|p| p.split_once('='))
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string()))
        .collect()
}
"}
